import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

import { DEFAULT_TICKET_COLUMNS, TicketColumnKey, isTicketColumnMandatory } from './ticketColumns'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface ticketColumnsLogicValues {
    columnSizing: Record<string, number>
    columnsAreDefault: boolean
    visibleColumns: TicketColumnKey[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface ticketColumnsLogicActions {
    resetColumns: () => {
        value: true
    }
    setColumnSizing: (columnSizing: Record<string, number>) => {
        columnSizing: Record<string, number>
    }
    setVisibleColumns: (columns: TicketColumnKey[]) => {
        columns: TicketColumnKey[]
    }
    toggleColumn: (column: TicketColumnKey) => {
        column: TicketColumnKey
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface ticketColumnsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        columnsAreDefault: (visibleColumns: TicketColumnKey[], columnSizing: Record<string, number>) => boolean
    }
}

export type ticketColumnsLogicType = MakeLogicType<
    ticketColumnsLogicValues,
    ticketColumnsLogicActions,
    Record<string, any>,
    ticketColumnsLogicMeta
>

/**
 * Which ticket table columns the user wants to see, and how wide they dragged each one. Deliberately not part of
 * supportTicketsSceneLogic: that logic is keyed per mount point (notebook nodes pass their
 * own nodeId), so a persisted reducer there would fragment the preference across instances.
 */
export const ticketColumnsLogic = kea<ticketColumnsLogicType>([
    path(['products', 'conversations', 'frontend', 'scenes', 'tickets', 'ticketColumnsLogic']),
    actions({
        setVisibleColumns: (columns: TicketColumnKey[]) => ({ columns }),
        toggleColumn: (column: TicketColumnKey) => ({ column }),
        setColumnSizing: (columnSizing: Record<string, number>) => ({ columnSizing }),
        resetColumns: true,
    }),
    reducers({
        visibleColumns: [
            DEFAULT_TICKET_COLUMNS as TicketColumnKey[],
            { persist: true },
            {
                setVisibleColumns: (_, { columns }) => columns,
                toggleColumn: (state, { column }) => {
                    if (isTicketColumnMandatory(column)) {
                        return state
                    }
                    return state.includes(column) ? state.filter((key) => key !== column) : [...state, column]
                },
                resetColumns: () => DEFAULT_TICKET_COLUMNS,
            },
        ],
        columnSizing: [
            {} as Record<string, number>,
            { persist: true },
            {
                setColumnSizing: (_, { columnSizing }) => columnSizing,
                resetColumns: () => ({}),
            },
        ],
    }),
    selectors({
        columnsAreDefault: [
            (s) => [s.visibleColumns, s.columnSizing],
            (visibleColumns: TicketColumnKey[], columnSizing: Record<string, number>): boolean =>
                Object.keys(columnSizing).length === 0 &&
                DEFAULT_TICKET_COLUMNS.every((key) => visibleColumns.includes(key)),
        ],
    }),
])
